do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-061","project":"hlvujbrmfdlrfxdjwsmb","actions":[{"ref":"a1","relation":"authors","key":{"open_library_id":"OL42200A"},"before":null,"after":{"name":"Atte Jongstra","open_library_id":"OL42200A","id":987360001}},{"ref":"a2","relation":"authors","key":{"open_library_id":"OL1450411A"},"before":null,"after":{"name":"Éric Vuillard","open_library_id":"OL1450411A","id":987360002}},{"ref":"w0","relation":"works","key":{"native_identity_key":"nlscale:20261102:ol:OL20244922W"},"before":null,"after":{"title":"Aan open zee","author_id":"@a1","first_publish_year":2016,"open_library_id":"OL20244922W","cover_id":8900406,"source_type":"open_library","work_type":"novel","native_identity_key":"nlscale:20261102:ol:OL20244922W","id":987160001}},{"ref":"e0","relation":"editions","key":{"open_library_edition_id":"OL27440391M"},"before":null,"after":{"work_id":"@w0","open_library_edition_id":"OL27440391M","isbn_13":"9789029505130","isbn_10":null,"title":"Aan open zee","language":"dut","publisher":"De Arbeiderspers","id":987260001,"publish_date":null,"cover_id":8900406}},{"ref":"d0","relation":"catalog_work_descriptions","key":{"work_id":"@w0","language":"nl"},"before":null,"after":{"work_id":"@w0","language":"nl","bound_author_id":"@a1","text":"Schrijver Axel Borg trekt voor de winter naar Christiansø, een klein Deens eiland in de Oostzee. Hij hoopt er eindelijk een groot boek te schrijven, maar de rust levert weinig inspiratie op. Dan spoelen er lichaamsdelen aan en krijgt het eiland onverwacht met geweld te maken. De bewoners en wintergasten proberen te begrijpen wat er gebeurt. Onder hen bevinden zich een politieman met verlof en een ondergedoken misdadiger. Terwijl Axel observeert, raken zijn schrijfplannen en de gebeurtenissen om hem heen steeds sterker verstrengeld.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.uitgeverijvolt.nl/de-arbeiderspers/boe